import itertools

def is_all_interval(perm):
    diffs = [abs(perm[i] - perm[i+1]) for i in range(10)]
    return len(set(diffs)) == 10 and min(diffs) == 1 and max(diffs) == 10

for perm in itertools.permutations(range(11)):
    if is_all_interval(perm):
        print(perm)
        break
else:
    print("No solution")
